path_block:
/v1/admin/model-providers/{provider_id}/upstream-models:
  get:
    tags: [Models]
    operationId: listAdminModelProviderUpstreamModels
    summary: Read upstream candidate model IDs for one saved provider
    description: Explicit current-platform-administrator read. No query, body framing, Content-Type, CAS or idempotency headers. Uses only the saved owner connection; candidates are not published models, capabilities, prices or execution authorization. No automatic retry or configuration mutation.
    x-kokoro-owner: kokoro-bff
    x-kokoro-visibility: public
    x-kokoro-stability: beta
    x-kokoro-idempotency: none
    x-kokoro-permission: admin.model_configuration.read
    parameters:
      - name: provider_id
        in: path
        required: true
        schema: { type: string, format: uuid }
    responses:
      '200':
        description: Candidate IDs from the exact saved provider; no credentials or upstream metadata.
        headers:
          x-request-id:
            required: true
            schema: { type: string, pattern: '^[A-Za-z0-9._:-]{1,128}$' }
          Cache-Control:
            required: true
            schema: { type: string, const: no-store }
          Content-Length:
            required: true
            schema: { type: string, pattern: '^[0-9]+$' }
        content:
          application/json:
            schema: { $ref: '#/components/schemas/AdminModelProviderUpstreamModelsResponse' }
      '400': { $ref: '#/components/responses/AdminModelRoutingBadRequest' }
      '401': { $ref: '#/components/responses/AdminModelRoutingUnauthorized' }
      '403': { $ref: '#/components/responses/AdminModelRoutingForbidden' }
      '404': { $ref: '#/components/responses/AdminModelRoutingNotFound' }
      '429': { $ref: '#/components/responses/AdminModelRoutingRateLimited' }
      '502': { $ref: '#/components/responses/AdminModelRoutingInvalidResponse' }
      '503': { $ref: '#/components/responses/AdminModelRoutingUnavailable' }
